#define X first
#define Y second
#define FOR(i, a, b) for(int i = (a); i < (b); i++)
#define FORE(i, a, b) for(int i = (a); i <= (b); i++)
#define FORD(i, a, b) for(int i = (a); i >= (b); i--)
#define bitcount(n) __builtin_popcountll(n)
template <typename T,typename U>
std::pair<T,U> operator+(const std::pair<T,U> & l,const std::pair<T,U> & r) {
  return {l.first+r.first,l.second+r.second};
} 
typedef void (*callback_function)(void);
const long long ZERO = 0LL;
const long long INF64 = 1e18;
const int INF32 = 1e9;
const int MOD = 1e9 + 7;
const double PI = acos(-1.0L);
const double EPS = static_cast<double>(1e-9);
typedef long long ll;

int mod(int a) {
  return ((a % MOD) + MOD) % MOD;
}

int product(int a, int b) {
  return int(a * 1LL * b % MOD);
}

int fastPow(int a, int k) {
  int res = 1;
  while (k > 0) {
    if (k & 1) res = product(res, a);
    a = product(a, a);
    k >>= 1;
  }
  return res;
}

int modularInverse(int a) {
  int b = fastPow(a, MOD - 2);
  assert(product(a, b) == 1);
  return b;
}

struct Edge {
  int y;
  int capacity;
  int flow;
  int cost;

  Edge() {};

  Edge(int _y, int _capacity, int _flow, int _cost) 
    : y(_y), capacity(_capacity), flow(_flow), cost(_cost) {};
};

vector<Edge> edgesList;

const int MAXNODES = 1e6 + 7;
vector<int> adj[MAXNODES];

ll totalCostAccum = 0;
ll distArr[MAXNODES];
int predArr[MAXNODES];
int peArr[MAXNODES];
int inQueueFlag[MAXNODES];

int src = MAXNODES - 2;
int tgt = MAXNODES - 1;

int residual(int x) {
  return edgesList[x].capacity - edgesList[x].flow;
}

void findAugment() {
  for (int i = 0; i < MAXNODES; i++) {
    distArr[i] = INF64;
    predArr[i] = -1;
    peArr[i] = -1;
    inQueueFlag[i] = 0;
  }
  distArr[src] = 0;
  std::queue<int> q;
  q.push(src);
  inQueueFlag[src] = 1;
  while (!q.empty()) {
    int u = q.front(); q.pop();
    inQueueFlag[u] = 0;
    for (auto eIdx : adj[u]) {
      if (!residual(eIdx)) continue;
      int cst = edgesList[eIdx].cost;
      int y = edgesList[eIdx].y;
      if (distArr[y] > distArr[u] + cst) {
        distArr[y] = distArr[u] + cst;
        predArr[y] = u;
        peArr[y] = eIdx;
        if (inQueueFlag[y] == 0) {
          inQueueFlag[y] = 1;
          q.push(y);
        }
      }
    }
  }
  int cur = tgt;
  while (cur != src) {
    edgesList[peArr[cur]].flow++;
    edgesList[peArr[cur] ^ 1].flow--;
    cur = predArr[cur];
  }
  totalCostAccum += distArr[tgt];
}

void createEdge(int x, int y, int cap, int cst) {
  adj[x].push_back(edgesList.size());
  edgesList.emplace_back(y, cap, 0, cst);
  adj[y].push_back(edgesList.size());
  edgesList.emplace_back(x, 0, 0, -cst);
}

int n, m, k, c, d;

void readData() {
